// TH15 v1.00b Stage 7 Extra 中Boss首符
// source st07mbs.ecl.txt:
//   MBoss1:44-51 (entry) -> MBossCard1:137-188 (spell) ->
//   MBossCard1_at:190-229 / MBossCard1_at2:231-242 (butterfly emitters)
// Source type22 = butterfly; TH15_* vocabulary is copied here as required.
const TH15_BUTTERFLY: int = 704;

const TIME_LIMIT: int = 3184;      // 120 opening buffer + 3060 source window + 4 startup margin
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 106;
const SOURCE_TIME: int = 3000;     // MBossCard1:169 slot0 HP0/time3000

// moveLimit(0, 128, 280, 64): center (0,128), full w/h -> x [-140,140], y [96,160].
const LIMIT_X: fx = 140fx;
const LIMIT_Y_MIN: fx = 96fx;
const LIMIT_Y_MAX: fx = 160fx;
// moveRand direction inner region is center +- w/4, center +- h/4.
const RAND_X: fx = 70fx;
const RAND_Y_LO: fx = 112fx;
const RAND_Y_HI: fx = 144fx;
// EX type 2 ANIM a=1: position -= 4 * velocity at spawn; source speed is 2.2.
const ANIM_BACK: fx = 8.8fx;

// source MBossCard1_at: etNew/etAim(3)/etSprite(22,1)/etCount(1,1);
// etAngle is overwritten by %ANGLE_PLAYER and %A = %ANGLE_PLAYER + %A.
// N=M=1, so mode3 uses only alpha: every shot of this call shares one aim snapshot.
sub mboss_at(start: angle, step: angle, dir: int) {
    var aim: angle = aim_player();                 // source %ANGLE_PLAYER (read once at config)
    var a: angle = aim + start;                    // source %A = %ANGLE_PLAYER + %A
    for i in 0..32 {                               // source $E = 32
        // source etOffsetRad(0, %A, -160.0f), then etOn from the current boss position.
        // EX ANIM a=1 also applies position -= 4*velocity (2.2 * 4 = 8.8 px).
        var px: fx = $self_x - 160fx * cos(a) - ANIM_BACK * cos(aim);
        var py: fx = $self_y - 160fx * sin(a) - ANIM_BACK * sin(aim);
        _ = fire(TH15_BUTTERFLY, 1, px, py, 2.2fx, aim, none, none);
        if dir > 0 { a = a + step; } else { a = a - step; } // source %A += %B/16
        wait(2);                                   // source wait(2) after every etOn
    }
}

// source MBossCard1_at2: $A=1000; pair of 32-shot calls; goto label @0 keeps 128-frame period.
async sub mboss_at2() {
    var n: int = 1000;
    while n > 0 {
        // -pi/2, +pi and +pi/2, -pi; 11.25 deg = pi/16 = 2048 BAM.
        mboss_at(49152 as angle, 2048 as angle, 1);
        mboss_at(16384 as angle, 2048 as angle, -1);
        n = n - 1;
    }
}

// source moveRand(120, 4, 1.0) at MBossCard1:181/183 and the repeated loop at 186.
// The speed slot keeps mode0 (linear): speed(k) = 1 - k/120, k=1..120.
// The position limit is applied every tick; target phase5 runs after ECL, so arm
// the next source movement tick now (same construction as the checked moveRand recipe).
sub arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 120 { speed = (120 - k) as fx / 120fx; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < 0fx - LIMIT_X { nx = 0fx - LIMIT_X; }
    if nx > LIMIT_X { nx = LIMIT_X; }
    if ny < LIMIT_Y_MIN { ny = LIMIT_Y_MIN; }
    if ny > LIMIT_Y_MAX { ny = LIMIT_Y_MAX; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// source moveRand direction selection: one signed random, central branch adds one WORD.
sub start_move_rand() {
    var r: int = rand(65536) - 32768;              // signed +-pi in BAM
    var a: int = r / 3;
    if $self_x < 0fx - RAND_X {
        a = r / 3;                                  // +-60 deg
    } else if $self_x > RAND_X {
        a = r / 3 + 32768;                          // wrap(+-60 deg + pi)
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;                                  // +-45 deg
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < RAND_Y_LO {
        if a < 0 { a = 0 - a; }                     // top: abs
    } else if $self_y > RAND_Y_HI {
        if a < 0 { a = 0 - a; }                     // bottom: -abs
        a = 0 - a;
    }
    // source +-pi/2 guard, epsilon 0.05 rad; nearest BAM boundaries.
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_next_step();
}

// source wait(240) after each moveRand; also stop the movement task at spell timeout.
sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        if spell_timer() < 0 { return; }
        arm_next_step();
    }
}

async sub boss_main() {
    // Training shell: the real boss is invulnerable; source setInvuln(60) at MBoss1:46
    // is covered by this permanent shell invulnerability.
    set_invuln(65535);
    // MBoss:24-25: setHurtbox(48,48) -> r24, setHitbox(40,40) -> r20 (normal circle).
    set_hurtbox(24fx);
    set_hitbox(20fx);

    // MBoss1:48: wait(60) charge; target card frame 0 is MBoss1:44.
    wait(60);

    // MBossCard1:150 timerReset and :169 slot0 interrupt become the 3000-frame spell timer.
    // The 4 pre-reset script frames (setChapter/unknown569/BossItemCard) are chapter/stat
    // bookkeeping and are omitted under the shared chapter/entry policy.
    spell_begin(0, SPELL_ID, none, SOURCE_TIME, 500000, 0, 0);

    // MBossCard1:171-173: movePosTime(60,4,0,144) then wait(60).
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    // MBossCard1:175 +90 from timerReset: 30 more frames to the first moveRand.
    wait(30);

    // MBossCard1:178 @MBossCard1_at2() async and :180/186 movement loop.
    spawn mboss_at2();
    while spell_timer() >= 0 {
        start_move_rand();
        card_wait(240);
        if spell_timer() < 0 { break; }
        start_move_rand();
        card_wait(240);
    }
}

sub main() {
    wait(OPENING_BUFFER);
    // Entry state from MBoss:10-32: lifeSet(2200); boss is already at (0,128) after
    // movePos(-192,-64)/movePosTime(100,4,0,128) and the wait at MBoss:29.
    _ = spawn_enemy(0fx, 128fx, 2200, 0, 0, 0, boss_main);
    wait(TIME_LIMIT + 300);
    loop { wait(600); }
}
